/**
 * 扩展行动库
 *
 * 涵盖：街头生存 / 经营 / 社交 / 学习 / 生活 / 投资 / 梦想实现
 * 参考：《北京浮生记》《大多数》《中国式家长》《这是我的战争》《Stardew Valley》
 *
 * 用法：getAvailableActions() 末尾会调用 addExtraActions() 把这些行动合并进去
 */

/** 街头阶段通用行动（不依赖地点） */
function addStreetExtras(state, actions) {
  // === 街头生存类（任何街头地点都行） ===
  actions.push({
    id: "scavenge_trash",
