    desc: "在巷子里翻垃圾桶找瓶瓶罐罐卖钱。脏但能赚点零花钱。",
    icon: "🗑️",
    apCost: 20,
    payEstimate: "2~9",
    handler: () => {
      const st = StateManager.getState();
      var base = 2 + Math.floor(Math.random() * 8);
      var bonus = 0;
      var bonusMsg = "";
      // 老周好感30解锁：知道好地段，废品多+¥5-12
      if (st.flags.oldZhouTips) {
        bonus += 5 + Math.floor(Math.random() * 8);
        bonusMsg = "（老周教的路线多翻了不少）";
      }
      // 老周好感80解锁：高价废品收购渠道，额外溢价
      if (st.flags.oldZhouChannel) {
        bonus += 8 + Math.floor(Math.random() * 12);
        bonusMsg = "（老周的高价渠道又多卖了一点）";
      }
      const earned = base + bonus;
      st.resources.cash += earned;
      st.needs.hygiene = Math.max(0, st.needs.hygiene - 5);
      st.needs.fatigue = Math.min(100, st.needs.fatigue + 5);
      st.resources.totalEarned += earned;
      StateManager.addMessage(
        `🗑️ 翻了半天垃圾桶，捡到 ¥${earned}${bonusMsg}，脏兮兮的。`,
        "success",
      );
      consumeAP(20);
    },
  });

  actions.push({
    id: "busking",
    name: "🎤 街头卖唱",
    desc: "在地铁口或天桥上唱歌赚打赏。需要胆子大。",
    icon: "🎤",
    apCost: 20,
    payEstimate: "5~25",
    handler: () => {
      const st = StateManager.getState();
      const skill = st.player.mental; // 心智影响成功率
      const earned = Math.floor(5 + Math.random() * 20 + (skill - 25) * 0.3);
      st.resources.cash += earned;
      st.resources.totalEarned += earned;
      st.needs.fatigue = Math.min(100, st.needs.fatigue + 10);
      st.status.fame = Math.min(100, st.status.fame + 1);
      if (Math.random() < 0.2) {
        st.needs.happiness = Math.max(0, st.needs.happiness - 5);
        StateManager.addMessage(
          `🎤 唱了半天，城管赶人+路人嫌弃，赚到 ¥${earned}。`,
          "warning",
        );
      } else {
        st.needs.happiness = Math.min(100, st.needs.happiness + 8);
        StateManager.addMessage(
          `🎤 卖唱结束，收获 ¥${earned} 打赏！心情好。`,
          "success",
        );
      }
      consumeAP(20);
    },
  });

  actions.push({
    id: "beg",
    name: "🙏 街头乞讨",
    desc: "放下尊严，跪地要饭。（有尊严损失）",
    icon: "🙏",
    apCost: 20,
    payEstimate: "1~5",
    handler: () => {
      const st = StateManager.getState();
      const earned = 1 + Math.floor(Math.random() * 5);
      st.resources.cash += earned;
      st.resources.totalEarned += earned;
      st.needs.happiness = Math.max(0, st.needs.happiness - 12);
      st.status.fame = Math.max(0, st.status.fame - 2);
      st.flags._everBegged = true; // 成就追踪
      StateManager.addMessage(
        `🙏 跪了半小时，收到 ¥${earned}。心里五味杂陈。`,
        "warning",
      );
      consumeAP(20);
    },

